contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address to, uint256 v) public payable {
        require(to != address(0));
        // Read balances before
        uint256 before_sender = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 before_recipient = c.balanceOf(to); if (__ESBMC_reverted()) return;

        // Ensure this contract is not frozen: only owner can change frozenAccount, but we can't assume owner
        // We attempt the transfer and record whether it reverted
        bool reverted;
        c.transfer(to, v); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 after_sender = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 after_recipient = c.balanceOf(to); if (__ESBMC_reverted()) return;

        // If transfer succeeded (didn't revert) then sender lost v and recipient gained v
        // Use inequalities that avoid underflow in the assert expression itself
        assert(reverted || (after_sender + v == before_sender && after_recipient == before_recipient + v));
    }
    receive() external payable {}
}

