pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(address to, uint256 v) internal {
        vm.assume(to != address(0));
        uint256 before_sender;
        try c.balanceOf(address(this)) returns (uint256 __r) { before_sender = __r; } catch { return; }
        uint256 before_recipient;
        try c.balanceOf(to) returns (uint256 __r) { before_recipient = __r; } catch { return; }
        bool reverted;
        try c.transfer(to, v) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 after_sender;
        try c.balanceOf(address(this)) returns (uint256 __r) { after_sender = __r; } catch { return; }
        uint256 after_recipient;
        try c.balanceOf(to) returns (uint256 __r) { after_recipient = __r; } catch { return; }
        assertTrue(reverted || (after_sender + v == before_sender && after_recipient == before_recipient + v));
    }

    function testFuzz_run(address to, uint256 v) public {
        vm.assume(to.code.length == 0 && uint160(to) > 0xffff && to != address(this) && to != address(c) && to != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && to != 0x000000000000000000636F6e736F6c652e6c6f67 && to != 0x4e59b44847b379578588920cA78FbF26c0B4956C && to != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(to, v);
    }

    receive() external payable {}
}
